        <?php else: ?><div class="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-slate-200 tw-bg-white tw-shadow-sm"><div class="tw-overflow-x-auto"><table class="tw-w-full tw-min-w-[760px] tw-text-left tw-text-sm"><thead class="tw-border-b tw-border-slate-200 tw-bg-slate-50 tw-text-xs tw-uppercase tw-tracking-wide tw-text-slate-500"><tr><th class="tw-px-5 tw-py-4">Siklus</th><th class="tw-px-5 tw-py-4">Tahun akademik</th><th class="tw-px-5 tw-py-4">Periode</th><th class="tw-px-5 tw-py-4">Status</th><th class="tw-px-5 tw-py-4"></th></tr></thead><tbody id="cycle-list" class="tw-divide-y tw-divide-slate-100"><?php foreach ($cycles as $cycle): ?><?php $academic_year = isset($cycle->academic_year) ? trim((string) $cycle->academic_year) : ''; $semester = isset($cycle->semester) ? strtolower(trim((string) $cycle->semester)) : ''; $academic_period = $academic_year !== '' && in_array($semester, ['ganjil', 'genap'], TRUE) ? $academic_year . ' — ' . ucfirst($semester) : 'Periode akademik belum dicatat'; ?><tr class="cycle-row hover:tw-bg-slate-50" data-search="<?php echo html_escape(strtolower($cycle->cycle_code . ' ' . $cycle->title)); ?>" data-status="<?php echo html_escape($cycle->state); ?>" data-year="<?php echo html_escape($academic_year); ?>"><td class="tw-px-5 tw-py-4"><div class="tw-font-bold tw-text-slate-900"><?php echo html_escape($cycle->cycle_code); ?></div><div class="tw-mt-1 tw-text-slate-500"><?php echo html_escape($cycle->title); ?></div></td><td class="tw-px-5 tw-py-4 tw-text-slate-600"><?php echo html_escape($academic_period ?? 'Periode akademik belum dicatat'); ?></td><td class="tw-px-5 tw-py-4 tw-whitespace-nowrap tw-text-slate-600"><?php echo html_escape($cycle->start_date . ' — ' . $cycle->end_date); ?></td><td class="tw-px-5 tw-py-4"><span class="tw-inline-flex tw-rounded-full tw-bg-slate-100 tw-px-2.5 tw-py-1 tw-text-xs tw-font-bold tw-text-slate-700"><?php echo html_escape($cycle->state); ?></span></td><td class="tw-px-5 tw-py-4 tw-text-right"><a class="tw-font-semibold tw-text-slate-950 hover:tw-underline" href="<?php echo site_url('lpmpi/spmi-audits/cycle/detail/' . (int) $cycle->id); ?>">Buka detail</a></td></tr><?php endforeach; ?></tbody></table></div><p id="cycle-filter-empty" class="tw-hidden tw-p-8 tw-text-center tw-text-sm tw-text-slate-500">Tidak ada siklus yang cocok.</p></div><?php endif; ?>
