<script>(function () { var rows = Array.prototype.slice.call(document.querySelectorAll('.cycle-row')); var search = document.getElementById('cycle-filter-search'); var status = document.getElementById('cycle-filter-status'); var year = document.getElementById('cycle-filter-year'); var empty = document.getElementById('cycle-filter-empty'); function filter() { var query = search.value.trim().toLocaleLowerCase(); var visible = rows.filter(function (row) { var match = (!query || row.dataset.search.indexOf(query) !== -1) && (!status.value || row.dataset.status === status.value) && (!year.value || row.dataset.year === year.value); row.classList.toggle('tw-hidden', !match); return match; }); if (empty) empty.classList.toggle('tw-hidden', visible.length !== 0); } [search, status, year].forEach(function (field) { if (field) field.addEventListener('input', filter); }); }());</script>
